import{_ as p,a0 as d,w as o,s as h,ao as l,I as t,a1 as e,A as n,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Linux 中查看已挂载的文件系统类型 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中查看已挂载的文件系统类型 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中查看已挂载的文件系统类型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中查看已挂载的文件系统类型 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180716 How To Find The Mounted Filesystem Type In Linux","title":"如何在 Linux 中查看已挂载的文件系统类型","tag":"201811","desc":""},"relativePath":"201811/20180716 How To Find The Mounted Filesystem Type In Linux.md","filePath":"[post].md"}'),c={name:"201811/20180716 How To Find The Mounted Filesystem Type In Linux.md"};function r(g,s,k,b,u,f){const i=d("Link");return o(),h("div",null,[s[16]||(s[16]=l(`<h1 id="如何在-linux-中查看已挂载的文件系统类型" tabindex="-1">如何在 Linux 中查看已挂载的文件系统类型 <a class="header-anchor" href="#如何在-linux-中查看已挂载的文件系统类型" aria-label="Permalink to “如何在 Linux 中查看已挂载的文件系统类型”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/07/filesystem-720x340.png" alt=""></p><p>如你所知，Linux 支持非常多的文件系统，例如 ext4、ext3、ext2、sysfs、securityfs、FAT16、FAT32、NTFS 等等，当前被使用最多的文件系统是 ext4。你曾经疑惑过你的 Linux 系统使用的是什么类型的文件系统吗？没有疑惑过？不用担心！我们将帮助你。本指南将解释如何在类 Unix 的操作系统中查看已挂载的文件系统类型。</p><h3 id="在-linux-中查看已挂载的文件系统类型" tabindex="-1">在 Linux 中查看已挂载的文件系统类型 <a class="header-anchor" href="#在-linux-中查看已挂载的文件系统类型" aria-label="Permalink to “在 Linux 中查看已挂载的文件系统类型”">​</a></h3><p>有很多种方法可以在 Linux 中查看已挂载的文件系统类型，下面我将给出 8 种不同的方法。那现在就让我们开始吧！</p><h4 id="方法-1-–-使用-findmnt-命令" tabindex="-1">方法 1 – 使用 findmnt 命令 <a class="header-anchor" href="#方法-1-–-使用-findmnt-命令" aria-label="Permalink to “方法 1 – 使用 findmnt 命令”">​</a></h4><p>这是查出文件系统类型最常使用的方法。<code>findmnt</code> 命令将列出所有已挂载的文件系统或者搜索出某个文件系统。<code>findmnt</code> 命令能够在 <code>/etc/fstab</code>、<code>/etc/mtab</code> 或 <code>/proc/self/mountinfo</code> 这几个文件中进行搜索。</p><p><code>findmnt</code> 预装在大多数的 Linux 发行版中，因为它是 <code>util-linux</code> 包的一部分。如果 <code>findmnt</code> 命令不可用，你可以安装这个软件包。例如，你可以使用下面的命令在基于 Debian 的系统中安装 <code>util-linux</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install util-linux</span></span></code></pre></div><p>下面让我们继续看看如何使用 <code>findmnt</code> 来找出已挂载的文件系统。</p><p>假如你只敲 <code>findmnt</code> 命令而不带任何的参数或选项，它将像下面展示的那样以树状图形式列举出所有已挂载的文件系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/findmnt-1.png" alt=""></p><p>正如你看到的那样，<code>findmnt</code> 展示出了目标挂载点（<code>TARGET</code>）、源设备（<code>SOURCE</code>）、文件系统类型（<code>FSTYPE</code>）以及相关的挂载选项（<code>OPTIONS</code>），例如文件系统是否是可读可写或者只读的。以我的系统为例，我的根（<code>/</code>）文件系统的类型是 EXT4 。</p><p>假如你不想以树状图的形式来展示输出，可以使用 <code>-l</code> 选项来以简单平凡的形式来展示输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt -l</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/findmnt-2.png" alt=""></p><p>你还可以使用 <code>-t</code> 选项来列举出特定类型的文件系统，例如下面展示的 <code>ext4</code> 文件系统类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt -t ext4</span></span>
<span class="line"><span>TARGET  SOURCE    FSTYPE OPTIONS</span></span>
<span class="line"><span>/       /dev/sda2 ext4   rw,relatime,commit=360</span></span>
<span class="line"><span>└─/boot /dev/sda1 ext4   rw,relatime,commit=360,data=ordered</span></span></code></pre></div><p><code>findmnt</code> 还可以生成 <code>df</code> 类型的输出，使用命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt --df</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt -D</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SOURCE     FSTYPE            SIZE    USED   AVAIL   USE% TARGET</span></span>
<span class="line"><span>dev        devtmpfs          3.9G       0    3.9G     0% /dev</span></span>
<span class="line"><span>run        tmpfs             3.9G    1.1M    3.9G     0% /run</span></span>
<span class="line"><span>/dev/sda2  ext4            456.3G  342.5G   90.6G    75% /</span></span>
<span class="line"><span>tmpfs      tmpfs             3.9G   32.2M    3.8G     1% /dev/shm</span></span>
<span class="line"><span>tmpfs      tmpfs             3.9G       0    3.9G     0% /sys/fs/cgroup</span></span>
<span class="line"><span>bpf        bpf                  0       0       0      - /sys/fs/bpf</span></span>
<span class="line"><span>tmpfs      tmpfs             3.9G    8.4M    3.9G     0% /tmp</span></span>
<span class="line"><span>/dev/loop0 squashfs         82.1M   82.1M       0   100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1  ext4             92.8M   55.7M   30.1M    60% /boot</span></span>
<span class="line"><span>tmpfs      tmpfs           788.8M     32K  788.8M     0% /run/user/1000</span></span>
<span class="line"><span>gvfsd-fuse fuse.gvfsd-fuse      0       0       0      - /run/user/1000/gvfs</span></span></code></pre></div><p>你还可以展示某个特定设备或者挂载点的文件系统类型。</p><p>查看某个特定的设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt /dev/sda1</span></span>
<span class="line"><span>TARGET SOURCE    FSTYPE OPTIONS</span></span>
<span class="line"><span>/boot  /dev/sda1 ext4   rw,relatime,commit=360,data=ordered</span></span></code></pre></div><p>查看某个特定的挂载点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt /</span></span>
<span class="line"><span>TARGET SOURCE    FSTYPE OPTIONS</span></span>
<span class="line"><span>/      /dev/sda2 ext4   rw,relatime,commit=360</span></span></code></pre></div><p>你甚至还可以查看某个特定标签的文件系统的类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ findmnt LABEL=Storage</span></span></code></pre></div><p>更多详情，请参考其 man 手册。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man findmnt</span></span></code></pre></div><p><code>findmnt</code> 命令已足够完成在 Linux 中查看已挂载文件系统类型的任务，这个命令就是为了这个特定任务而生的。然而，还存在其他方法来查看文件系统的类型，假如你感兴趣的话，请接着往下看。</p><h4 id="方法-2-–-使用-blkid-命令" tabindex="-1">方法 2 – 使用 blkid 命令 <a class="header-anchor" href="#方法-2-–-使用-blkid-命令" aria-label="Permalink to “方法 2 – 使用 blkid 命令”">​</a></h4><p><code>blkid</code> 命令被用来查找和打印块设备的属性。它也是 <code>util-linux</code> 包的一部分，所以你不必再安装它。</p><p>为了使用 <code>blkid</code> 命令来查看某个文件系统的类型，可以运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ blkid /dev/sda1</span></span></code></pre></div><h4 id="方法-3-–-使用-df-命令" tabindex="-1">方法 3 – 使用 df 命令 <a class="header-anchor" href="#方法-3-–-使用-df-命令" aria-label="Permalink to “方法 3 – 使用 df 命令”">​</a></h4><p>在类 Unix 的操作系统中，<code>df</code> 命令被用来报告文件系统的磁盘空间使用情况。为了查看所有已挂载文件系统的类型，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -T</span></span></code></pre></div><p>示例输出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/df.png" alt=""></p><p>关于 <code>df</code> 命令的更多细节，可以参考下面的指南。</p>`,46)),t("ul",null,[t("li",null,[e(i,{href:"https://www.ostechnix.com/the-df-command-tutorial-with-examples-for-beginners/"},{default:n(()=>[...s[0]||(s[0]=[a("针对新手的 df 命令教程",-1)])]),_:1})])]),s[17]||(s[17]=l(`<p>同样也可以参考其 man 手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man df</span></span></code></pre></div><h4 id="方法-4-–-使用-file-命令" tabindex="-1">方法 4 – 使用 file 命令 <a class="header-anchor" href="#方法-4-–-使用-file-命令" aria-label="Permalink to “方法 4 – 使用 file 命令”">​</a></h4><p><code>file</code> 命令可以判读出某个特定文件的类型，即便该文件没有文件后缀名也同样适用。</p><p>运行下面的命令来找出某个特定分区的文件系统类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo file -sL /dev/sda1</span></span>
<span class="line"><span>[sudo] password for sk:</span></span>
<span class="line"><span>/dev/sda1: Linux rev 1.0 ext4 filesystem data, UUID=83a1dbbf-1e15-4b45-94fe-134d3872af96 (needs journal recovery) (extents) (large files) (huge files)</span></span></code></pre></div><p>查看其 man 手册可以知晓更多细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man file</span></span></code></pre></div><h4 id="方法-5-–-使用-fsck-命令" tabindex="-1">方法 5 – 使用 fsck 命令 <a class="header-anchor" href="#方法-5-–-使用-fsck-命令" aria-label="Permalink to “方法 5 – 使用 fsck 命令”">​</a></h4><p><code>fsck</code> 命令被用来检查某个文件系统是否健全或者修复它。你可以像下面那样通过将分区名字作为 <code>fsck</code> 的参数来查看该分区的文件系统类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fsck -N /dev/sda1</span></span>
<span class="line"><span>fsck from util-linux 2.32</span></span>
<span class="line"><span>[/usr/bin/fsck.ext4 (1) -- /boot] fsck.ext4 /dev/sda1</span></span></code></pre></div><p>如果想知道更多的内容，请查看其 man 手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man fsck</span></span></code></pre></div><h4 id="方法-6-–-使用-fstab-命令" tabindex="-1">方法 6 – 使用 fstab 命令 <a class="header-anchor" href="#方法-6-–-使用-fstab-命令" aria-label="Permalink to “方法 6 – 使用 fstab 命令”">​</a></h4><p><code>fstab</code> 是一个包含文件系统静态信息的文件。这个文件通常包含了挂载点、文件系统类型和挂载选项等信息。</p><p>要查看某个文件系统的类型，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/fstab</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/07/fstab.png" alt=""></p><p>更多详情，请查看其 man 手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man fstab</span></span></code></pre></div><h4 id="方法-7-–-使用-lsblk-命令" tabindex="-1">方法 7 – 使用 lsblk 命令 <a class="header-anchor" href="#方法-7-–-使用-lsblk-命令" aria-label="Permalink to “方法 7 – 使用 lsblk 命令”">​</a></h4><p><code>lsblk</code> 命令可以展示设备的信息。</p><p>要展示已挂载文件系统的信息，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsblk -f</span></span>
<span class="line"><span>NAME   FSTYPE   LABEL  UUID                                 MOUNTPOINT</span></span>
<span class="line"><span>loop0  squashfs                                             /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>sda</span></span>
<span class="line"><span>├─sda1 ext4            83a1dbbf-1e15-4b45-94fe-134d3872af96 /boot</span></span>
<span class="line"><span>├─sda2 ext4            4d25ddb0-5b20-40b4-ae35-ef96376d6594 /</span></span>
<span class="line"><span>└─sda3 swap            1f8f5e2e-7c17-4f35-97e6-8bce7a4849cb [SWAP]</span></span>
<span class="line"><span>sr0</span></span></code></pre></div><p>更多细节，可以参考它的 man 手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man lsblk</span></span></code></pre></div><h4 id="方法-8-–-使用-mount-命令" tabindex="-1">方法 8 – 使用 mount 命令 <a class="header-anchor" href="#方法-8-–-使用-mount-命令" aria-label="Permalink to “方法 8 – 使用 mount 命令”">​</a></h4><p><code>mount</code> 被用来在类 Unix 系统中挂载本地或远程的文件系统。</p><p>要使用 <code>mount</code> 命令查看文件系统的类型，可以像下面这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mount | grep &quot;^/dev&quot;</span></span>
<span class="line"><span>/dev/sda2 on / type ext4 (rw,relatime,commit=360)</span></span>
<span class="line"><span>/dev/sda1 on /boot type ext4 (rw,relatime,commit=360,data=ordered)</span></span></code></pre></div><p>更多详情，请参考其 man 手册的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man mount</span></span></code></pre></div><p>好了，上面便是今天的全部内容了。现在你知道了 8 种不同的 Linux 命令来查看已挂载的 Linux 文件系统的类型。假如你知道其他的命令来完成同样的任务，请在下面的评论部分让我们知晓，我将确认并相应地升级本教程。</p><p>更过精彩内容即将呈现，请保持关注！</p><hr>`,35)),t("p",null,[s[2]||(s[2]=a("via: ",-1)),e(i,{href:"https://www.ostechnix.com/how-to-find-the-mounted-filesystem-type-in-linux/"},{default:n(()=>[...s[1]||(s[1]=[a("https://www.ostechnix.com/how-to-find-the-mounted-filesystem-type-in-linux/",-1)])]),_:1})]),t("p",null,[s[7]||(s[7]=a("作者：",-1)),e(i,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...s[3]||(s[3]=[a("SK",-1)])]),_:1}),s[8]||(s[8]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),e(i,{href:"https://github.com/FSSlc"},{default:n(()=>[...s[5]||(s[5]=[a("FSSlc",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[6]||(s[6]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const v=p(c,[["render",r]]);export{y as __pageData,v as default};
